def absDifference(a, b):
    if len(a) != len(b):
        x, y = (a, b) if len(a) > len(b) else (b, a)
    else:
        x, y = (a, b) if a >= b else (b, a)
    res = []
    borrow = 0
    j = len(y) - 1
    for i in range(len(x) - 1, -1, -1):
        d = x[i] - borrow - (y[j] if j >= 0 else 0)
        j -= 1
        if d < 0:
            d += 10
            borrow = 1
        else:
            borrow = 0
        res.append(d)
    while len(res) > 1 and res[-1] == 0:
        res.pop()
    res.reverse()
    return res
